package scan

import "fmt"

type styleEntry struct {
	name        string
	line        int
	autoAllowed bool
}

// StyleMethod is one Styled method generated by a gpui_macros style macro.
type StyleMethod struct {
	Name  string
	Macro string
	Line  int
}

type styleSrc struct {
	p      *fileParser
	fns    map[string][2]int
	tables map[string][]styleEntry
}

// ExpandStyles expands the style macros of gpui_macros/src/styles.rs into the method names they generate.
func ExpandStyles(src string) ([]StyleMethod, error) {
	p := &fileParser{toks: lex(src)}
	s := &styleSrc{p: p, fns: map[string][2]int{}, tables: map[string][]styleEntry{}}
	for i := 0; i+1 < len(p.toks); i++ {
		if !p.kw(i, "fn") || p.tok(i+1).kind != tIdent {
			continue
		}
		name := p.tok(i + 1).text
		j := p.skipToBodyOrSemi(i+2, len(p.toks))
		if j >= len(p.toks) || !p.punct(j, "{") {
			continue
		}
		e := p.match(j)
		s.fns[name] = [2]int{j + 1, e}
		if p.punct(i+2, "(") && p.punct(i+3, ")") && p.punct(i+4, "-") && p.kw(i+6, "Vec") {
			s.tables[name] = s.table(j+1, e)
		}
		i = e
	}
	var out []StyleMethod
	order := s.macroOrder()
	for _, m := range order {
		methods, err := s.expand(m, s.fns[m], 0)
		if err != nil {
			return nil, err
		}
		out = append(out, methods...)
	}
	return out, nil
}

func (s *styleSrc) macroOrder() []string {
	p := s.p
	var names []string
	for i := 0; i+5 < len(p.toks); i++ {
		if p.kw(i, "pub") && p.kw(i+1, "fn") && p.punct(i+3, "(") && p.kw(i+4, "input") {
			names = append(names, p.tok(i+2).text)
		}
	}
	return names
}

func (s *styleSrc) table(i, e int) []styleEntry {
	p := s.p
	var out []styleEntry
	for k := i; k < e; k++ {
		if p.tok(k).kind == tIdent && p.punct(k+1, "{") && (p.kw(k, "BoxStylePrefix") || p.kw(k, "BoxStyleSuffix") || p.kw(k, "CornerStylePrefix") || p.kw(k, "CornerStyleSuffix") || p.kw(k, "BorderStylePrefix") || p.kw(k, "BorderStyleSuffix")) {
			end := p.match(k + 1)
			ent := styleEntry{}
			for m := k + 2; m < end; m++ {
				if (p.kw(m, "prefix") || p.kw(m, "suffix")) && p.punct(m+1, ":") && p.tok(m+2).kind == tStr {
					ent.name = p.tok(m + 2).text
					ent.line = p.tok(m + 2).line
				}
				if p.kw(m, "auto_allowed") && p.punct(m+1, ":") {
					ent.autoAllowed = p.kw(m+2, "true")
				}
			}
			out = append(out, ent)
			k = end
		}
	}
	return out
}

func (s *styleSrc) call(k int, fn string) (string, string, bool) {
	p := s.p
	if !p.kw(k, fn) || !p.punct(k+1, "(") {
		return "", "", false
	}
	a := p.tok(k + 2).text
	if !p.punct(k+3, "(") || !p.punct(k+4, ")") || !p.punct(k+5, ",") {
		return "", "", false
	}
	b := p.tok(k + 6).text
	return a, b, true
}

func (s *styleSrc) expand(macro string, span [2]int, depth int) ([]StyleMethod, error) {
	if depth > 4 {
		return nil, fmt.Errorf("styles.rs: call depth exceeded in %s", macro)
	}
	p := s.p
	var out []StyleMethod
	for k := span[0]; k < span[1]; k++ {
		switch {
		case p.punct(k, "#") && p.kw(k+1, "visibility") && p.kw(k+2, "fn"):
			out = append(out, StyleMethod{Name: p.tok(k + 3).text, Macro: macro, Line: p.tok(k + 3).line})
		case p.kw(k, "generate_methods") && p.punct(k+1, "(") && p.punct(k+2, ")"):
			sub, ok := s.fns["generate_methods"]
			if !ok {
				return nil, fmt.Errorf("styles.rs: generate_methods not found")
			}
			ms, err := s.expand(macro, sub, depth+1)
			if err != nil {
				return nil, err
			}
			out = append(out, ms...)
			k += 2
		default:
			if a, b, ok := s.call(k, "generate_box_style_methods"); ok {
				ms, err := s.box(macro, a, b)
				if err != nil {
					return nil, err
				}
				out = append(out, ms...)
				k += 6
				continue
			}
			if p.kw(k, "for") && p.tok(k+1).kind == tIdent && p.kw(k+2, "in") && p.punct(k+4, "(") {
				outer := p.tok(k + 3).text
				body := p.skipTo(k+5, span[1], "{")
				end := p.match(body)
				inner := ""
				for m := body + 1; m < end; m++ {
					if p.kw(m, "for") && p.kw(m+2, "in") && p.punct(m+4, "(") {
						inner = p.tok(m + 3).text
						break
					}
				}
				if inner == "" {
					return nil, fmt.Errorf("styles.rs: loop over %s has no suffix loop", outer)
				}
				ms, err := s.simple(macro, outer, inner)
				if err != nil {
					return nil, err
				}
				out = append(out, ms...)
				k = end
			}
		}
	}
	return out, nil
}

func (s *styleSrc) tablesFor(a, b string) ([]styleEntry, []styleEntry, error) {
	pre, ok := s.tables[a]
	if !ok {
		return nil, nil, fmt.Errorf("styles.rs: table %s not found", a)
	}
	suf, ok := s.tables[b]
	if !ok {
		return nil, nil, fmt.Errorf("styles.rs: table %s not found", b)
	}
	return pre, suf, nil
}

func setterName(prefix, neg, suffix string) string {
	if suffix == "" {
		return prefix + neg
	}
	return prefix + neg + "_" + suffix
}

func (s *styleSrc) box(macro, a, b string) ([]StyleMethod, error) {
	pre, suf, err := s.tablesFor(a, b)
	if err != nil {
		return nil, err
	}
	var out []StyleMethod
	for _, px := range pre {
		out = append(out, StyleMethod{Name: px.name, Macro: macro, Line: px.line})
		for _, sx := range suf {
			if sx.name != "auto" || px.autoAllowed {
				out = append(out, StyleMethod{Name: setterName(px.name, "", sx.name), Macro: macro, Line: px.line})
			}
			if sx.name != "auto" {
				out = append(out, StyleMethod{Name: setterName(px.name, "_neg", sx.name), Macro: macro, Line: px.line})
			}
		}
	}
	return out, nil
}

func (s *styleSrc) simple(macro, a, b string) ([]StyleMethod, error) {
	pre, suf, err := s.tablesFor(a, b)
	if err != nil {
		return nil, err
	}
	var out []StyleMethod
	for _, px := range pre {
		out = append(out, StyleMethod{Name: px.name, Macro: macro, Line: px.line})
		for _, sx := range suf {
			out = append(out, StyleMethod{Name: setterName(px.name, "", sx.name), Macro: macro, Line: px.line})
		}
	}
	return out, nil
}
